import {createContext, useCallback, use, useState, useMemo} from 'react'
import type {CIFinding} from './ci-findings-types'

type BatchedFinding = {
  findingId: string
  finding: CIFinding
}

type CIFindingsBatchContextType = {
  batchedFindings: BatchedFinding[]
  isBatched: (findingId: string) => boolean
  addToBatch: (finding: CIFinding) => void
  removeFromBatch: (findingId: string) => void
  clearBatch: () => void
  batchSize: number
}

const CIFindingsBatchContext = createContext<CIFindingsBatchContextType | null>(null)

export function useCIFindingsBatch(): CIFindingsBatchContextType {
  const ctx = use(CIFindingsBatchContext)
  if (!ctx) throw new Error('useCIFindingsBatch must be used within CIFindingsBatchProvider')
  return ctx
}

export function CIFindingsBatchProvider({children}: {children: React.ReactNode}) {
  const [batchedFindings, setBatchedFindings] = useState<BatchedFinding[]>([])

  const isBatched = useCallback(
    (findingId: string) => batchedFindings.some(b => b.findingId === findingId),
    [batchedFindings],
  )

  const addToBatch = useCallback((finding: CIFinding) => {
    setBatchedFindings(prev => {
      if (prev.some(b => b.findingId === finding.id)) return prev
      return [...prev, {findingId: finding.id, finding}]
    })
  }, [])

  const removeFromBatch = useCallback((findingId: string) => {
    setBatchedFindings(prev => prev.filter(b => b.findingId !== findingId))
  }, [])

  const clearBatch = useCallback(() => {
    setBatchedFindings([])
  }, [])

  const value = useMemo(
    () => ({
      batchedFindings,
      isBatched,
      addToBatch,
      removeFromBatch,
      clearBatch,
      batchSize: batchedFindings.length,
    }),
    [batchedFindings, isBatched, addToBatch, removeFromBatch, clearBatch],
  )

  return <CIFindingsBatchContext value={value}>{children}</CIFindingsBatchContext>
}
