import {
  FileIcon,
  BeakerIcon,
  ToolsIcon,
  AlertIcon,
  BugIcon,
  ServerIcon,
  ChevronDownIcon,
  ChevronRightIcon,
} from '@primer/octicons-react'
import type {Icon} from '@primer/octicons-react'
import {Octicon} from '@primer/react/deprecated'
import {useCallback, useMemo, useRef, useState} from 'react'
