import type {DiffEntry, StaticDiffLine} from '@github-ui/diff-lines/conversation-types'
import {usePageDataContext} from '@github-ui/pull-request-page-data-tooling/page-data-context'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {CIFinding, FixDiffHunk} from './ci-findings-types'
import {useCIFindings} from './use-ci-findings'
import {useCIFindingsBatch} from './CIFindingsBatchContext'
import styles from './FailureAnalysisPanel.module.css'

const CATEGORY_CONFIG: Record<
  string,
  {
    label: string
    variant: 'default' | 'accent' | 'attention' | 'severe' | 'danger' | 'done' | 'sponsors' | 'secondary'
    icon: Icon
  }
> = {
  test_failure: {label: 'Test Failure', variant: 'danger', icon: BeakerIcon},
  build_failure: {label: 'Build Failure', variant: 'severe', icon: ToolsIcon},
  lint: {label: 'Lint', variant: 'attention', icon: AlertIcon},
  infrastructure: {label: 'Infrastructure', variant: 'secondary', icon: ServerIcon},
}

function CategoryLabel({category}: {category: string}) {
  const config = CATEGORY_CONFIG[category] ?? {label: category, variant: 'default' as const}
  return (
    <Label variant={config.variant} size="small">
      {config.label}
    </Label>
  )
}

function CodeAnchor({filePath, startLine, endLine}: {filePath: string; startLine?: number; endLine?: number}) {
  const lineRange =
    startLine && endLine
      ? startLine === endLine
        ? `L${startLine}`
        : `L${startLine}-L${endLine}`
      : startLine
        ? `L${startLine}`
        : null

  return (
    <div className={styles.codeAnchor}>
      <Octicon icon={FileIcon} className="fgColor-muted mr-1" />
      <span className="text-mono text-small">
        {filePath}
        {lineRange && <span className="fgColor-accent">:{lineRange}</span>}
      </span>
    </div>
  )
}

/**
 * Converts a FixDiffHunk into a DiffEntry compatible with StaticUnifiedDiffPreview.
 * Deletion lines represent the original code range, addition lines represent the suggestion.
 */
export function hunkToDiffEntry(hunk: FixDiffHunk): DiffEntry {
  const diffLines: StaticDiffLine[] = []

  // Deletion lines for the original range
  const originalLines = hunk.originalContent?.split('\n')
  for (let i = hunk.startLine; i <= hunk.endLine; i++) {
    const lineIdx = i - hunk.startLine
    const text = originalLines?.[lineIdx] ?? `  (original line ${i})`
    diffLines.push({
      left: i,
      right: null,
      type: 'DELETION',
      html: escapeHtml(text),
      text,
    })
  }

  // Addition lines for the suggestion
  const suggestionLines = hunk.suggestion.split('\n')
  for (const [idx, line] of suggestionLines.entries()) {
    diffLines.push({
      left: null,
      right: hunk.startLine + idx,
      type: 'ADDITION',
      html: escapeHtml(line),
      text: line,
    })
  }

  return {path: hunk.filePath, diffLines}
}

function escapeHtml(str: string): string {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

function SuggestionDiffEntry({diffEntry}: {diffEntry: DiffEntry}) {
  const [isCollapsed, setIsCollapsed] = useState(false)

  return (
    <div className="d-flex flex-column overflow-hidden mb-2">
      <div className={styles.diffEntryHeader}>
        <IconButton
          aria-label={isCollapsed ? 'Expand diff' : 'Collapse diff'}
          icon={isCollapsed ? ChevronRightIcon : ChevronDownIcon}
          size="small"
          variant="invisible"
          onClick={() => setIsCollapsed(!isCollapsed)}
        />
        <span className="text-mono text-small">{diffEntry.path}</span>
      </div>
      {!isCollapsed && (
        <StaticUnifiedDiffPreview
          tabSize={4}
          className={styles.diffPreview}
          diffTableClassName="borderColor-default"
          diffLines={diffEntry.diffLines}
        />
      )}
    </div>
  )
}

/**
 * Applies CI finding suggestions by sending fixDiffHunks to the backend,
 * which commits the changes directly without CCA.
 */
async function applyCIFindings(
  basePath: string,
  findings: CIFinding[],
  commitMessage: string,
): Promise<{commit_oid: string; finding_ids: string[]}> {
  const fixDiffHunks = findings.flatMap(f => f.fixDiffHunks ?? [])

  const response = await verifiedFetchJSON(`${basePath}/ci_analysis/apply_suggestions`, {
    method: 'POST',
    body: {
      finding_ids: findings.map(f => f.id),
      fix_diff_hunks: fixDiffHunks,
      commit_message: commitMessage,
    },
  })

  if (!response.ok) {
    let data = null
    try {
      data = await response.json()
    } catch {
      // ignore JSON parse errors
    }
    throw new Error(data?.error || 'Failed to apply CI fix suggestions')
  }

  return response.json()
}

function SuggestionChangeset({hunks, finding}: {hunks: FixDiffHunk[]; finding: CIFinding}) {
  const diffEntries = hunks.map(hunkToDiffEntry)
  const {isBatched, addToBatch, removeFromBatch, batchSize} = useCIFindingsBatch()
  const pendingInBatch = isBatched(finding.id)
  const hasBatchedItems = batchSize > 0
  const [isApplyDialogOpen, setIsApplyDialogOpen] = useState(false)
  const [isApplied, setIsApplied] = useState(false)
  const applyButtonRef = useRef<HTMLButtonElement>(null)
  const {basePageDataUrl} = usePageDataContext()

  const handleApplyCommit = async (
    commitMessage: string,
    onError: (error: Error, type?: string, friendlyMessage?: string) => void,
    onCompleted: () => void,
  ) => {
    try {
      await applyCIFindings(basePageDataUrl, [finding], commitMessage)
      setIsApplyDialogOpen(false)
      setIsApplied(true)
      onCompleted()
    } catch (e: unknown) {
      onError(
        e instanceof Error ? e : new Error('Unknown error'),
        'applyCIFindingSuggestion',
        'Failed to apply CI fix suggestion. Please try again.',
      )
    }
  }

  if (isApplied) {
    return (
      <div className={styles.fixSection}>
        <div className="d-flex flex-items-center gap-2">
          <Label variant="done" size="small">
            Applied
          </Label>
          <span className="text-small fgColor-muted">This suggestion has been applied.</span>
        </div>
      </div>
    )
  }

  return (
    <div className={styles.fixSection}>
      <div className="d-flex flex-items-center flex-justify-between mb-2">
        <h3 className="text-small text-bold fgColor-muted">
          Suggested changeset <CounterLabel scheme="secondary">{diffEntries.length}</CounterLabel>
        </h3>
      </div>

      {diffEntries.map(entry => (
        <SuggestionDiffEntry key={entry.path} diffEntry={entry} />
      ))}

      <div className="d-flex gap-2 flex-items-center flex-justify-end flex-wrap pt-2">
        {pendingInBatch && (
          <div className="flex-1">
            <Label variant="attention" size="small">
              Pending in batch
            </Label>
          </div>
        )}
        {!pendingInBatch && (
          <Button
            ref={applyButtonRef}
            variant="default"
            size="small"
            disabled={hasBatchedItems}
            onClick={() => setIsApplyDialogOpen(true)}
          >
            Apply suggestion
          </Button>
        )}
        <Button
          variant={pendingInBatch ? 'danger' : 'primary'}
          size="small"
          onClick={() => {
            if (pendingInBatch) {
              removeFromBatch(finding.id)
            } else {
              addToBatch(finding)
            }
          }}
        >
          {pendingInBatch ? 'Remove from batch' : 'Add to batch'}
        </Button>
      </div>

      {isApplyDialogOpen && (
        <ApplySuggestionDialog
          authorLogins={['copilot']}
          batchSize={diffEntries.length}
          defaultCommitMessage={`Apply CI fix: ${finding.title}`}
          dialogTitle="Apply suggestion"
          onClose={() => setIsApplyDialogOpen(false)}
          onCommit={handleApplyCommit}
          returnFocusRef={applyButtonRef}
          commentKind="ccr"
        />
      )}
    </div>
  )
}

function FindingCard({finding}: {finding: CIFinding}) {
  const categoryIcon = CATEGORY_CONFIG[finding.category]?.icon ?? BugIcon

  return (
    <div className={styles.findingCard}>
      <div className={styles.findingHeader}>
        <div className={styles.findingHeaderLeft}>
          <Octicon icon={categoryIcon} className="fgColor-muted flex-shrink-0 mt-1" />
          <h2 className={styles.findingTitle}>{finding.title}</h2>
        </div>
        <div className="flex-shrink-0">
          <CategoryLabel category={finding.category} />
        </div>
      </div>

      {finding.filePath && (
        <CodeAnchor filePath={finding.filePath} startLine={finding.startLine} endLine={finding.endLine} />
      )}

      <div className={styles.findingMessage}>{finding.message}</div>

      {finding.fixDiffHunks && finding.fixDiffHunks.length > 0 && (
        <SuggestionChangeset hunks={finding.fixDiffHunks} finding={finding} />
      )}

      <div className={styles.checkRunLabel}>
        <span className="text-small fgColor-muted">From: {finding.failedCheckRunName}</span>
        {finding.fixType && (
          <Label variant="accent" size="small" className="ml-2">
            {finding.fixType === 'code_change'
              ? 'Code change'
              : finding.fixType === 'retry'
                ? 'Retry'
                : finding.fixType}
          </Label>
        )}
      </div>
    </div>
  )
}

function focusOnMount(el: HTMLDivElement | null) {
  el?.focus()
}

function ApplyAllHeader({findings}: {findings: CIFinding[]}) {
  const fixableFindings = useMemo(() => findings.filter(f => f.fixDiffHunks && f.fixDiffHunks.length > 0), [findings])
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [isApplied, setIsApplied] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)
  const {basePageDataUrl} = usePageDataContext()
  const {batchSize} = useCIFindingsBatch()

  const handleCommit = useCallback(
    async (
      commitMessage: string,
      onError: (error: Error, type?: string, friendlyMessage?: string) => void,
      onCompleted: () => void,
    ) => {
      try {
        await applyCIFindings(basePageDataUrl, fixableFindings, commitMessage)
        setIsDialogOpen(false)
        setIsApplied(true)
        onCompleted()
      } catch (e: unknown) {
        onError(
          e instanceof Error ? e : new Error('Unknown error'),
          'applyAllCIFindings',
          'Failed to apply all CI fix suggestions. Please try again.',
        )
      }
    },
    [basePageDataUrl, fixableFindings],
  )

  if (fixableFindings.length === 0 || batchSize > 0) return null

  if (isApplied) {
    return (
      <div className={styles.applyAllHeader} ref={focusOnMount} tabIndex={-1}>
        <div className="d-flex flex-items-center gap-2">
          <Label variant="done" size="small">
            Applied
          </Label>
          <span className="text-small fgColor-muted">All suggestions have been applied.</span>
        </div>
      </div>
    )
  }

  return (
    <div className={styles.applyAllHeader}>
      <span className="text-bold">
        {fixableFindings.length} suggested fix{fixableFindings.length !== 1 ? 'es' : ''} available
      </span>
      <Button ref={buttonRef} variant="primary" size="small" onClick={() => setIsDialogOpen(true)}>
        Apply all
        <CounterLabel scheme="secondary" className={`ml-1 ${styles.buttonCounter}`}>
          {fixableFindings.length}
        </CounterLabel>
      </Button>
      {isDialogOpen && (
        <ApplySuggestionDialog
          authorLogins={['copilot']}
          batchSize={fixableFindings.length}
          commentKind="ccr"
          defaultCommitMessage={`Apply ${fixableFindings.length} CI fix suggestion${fixableFindings.length !== 1 ? 's' : ''} from Copilot`}
          dialogTitle="Apply all suggestions"
          onClose={() => setIsDialogOpen(false)}
          onCommit={handleCommit}
          returnFocusRef={buttonRef}
        />
      )}
    </div>
  )
}

function ApplyBatchHeader() {
  const {batchedFindings, batchSize, clearBatch} = useCIFindingsBatch()
  const [isBatchDialogOpen, setIsBatchDialogOpen] = useState(false)
  const applyBatchButtonRef = useRef<HTMLButtonElement>(null)
  const {basePageDataUrl} = usePageDataContext()

  const handleBatchCommit = useCallback(
    async (
      commitMessage: string,
      onError: (error: Error, type?: string, friendlyMessage?: string) => void,
      onCompleted: () => void,
    ) => {
      try {
        const findings = batchedFindings.map(b => b.finding)
        await applyCIFindings(basePageDataUrl, findings, commitMessage)
        clearBatch()
        setIsBatchDialogOpen(false)
        onCompleted()
      } catch (e: unknown) {
        onError(
          e instanceof Error ? e : new Error('Unknown error'),
          'applyCIFindingsBatch',
          'Failed to apply CI fix suggestions. Please try again.',
        )
      }
    },
    [basePageDataUrl, batchedFindings, clearBatch],
  )

  if (batchSize === 0) return null

  return (
    <div className={styles.batchHeader}>
      <div className="d-flex flex-items-center gap-2">
        <span className="text-bold">
          {batchSize} suggestion{batchSize !== 1 ? 's' : ''} in batch
        </span>
        <Label variant="attention" size="small">
          Pending
        </Label>
      </div>
      <Button ref={applyBatchButtonRef} variant="primary" size="small" onClick={() => setIsBatchDialogOpen(true)}>
        Apply batch
        <CounterLabel scheme="secondary" className={`ml-1 ${styles.buttonCounter}`}>
          {batchSize}
        </CounterLabel>
      </Button>
      {isBatchDialogOpen && (
        <ApplySuggestionDialog
          authorLogins={['copilot']}
          batchSize={batchSize}
          defaultCommitMessage={`Apply ${batchSize} CI fix suggestion${batchSize !== 1 ? 's' : ''} from Copilot`}
          dialogTitle="Apply suggestions"
          onClose={() => setIsBatchDialogOpen(false)}
          onCommit={handleBatchCommit}
          onDiscardBatch={() => {
            clearBatch()
            setIsBatchDialogOpen(false)
          }}
          returnFocusRef={applyBatchButtonRef}
          commentKind="ccr"
        />
      )}
    </div>
  )
}

export function FailureAnalysisPanel() {
  const {findings} = useCIFindings()

  if (findings.length === 0) {
    return (
      <div className="p-3 text-center">
        <span className="fgColor-muted">No failure analysis available yet.</span>
      </div>
    )
  }

  return (
    <div className={styles.panel}>
      <ApplyAllHeader findings={findings} />
      <ApplyBatchHeader />
      <p className="fgColor-muted mb-3 text-small">
        Copilot analyzed {findings.length} CI failure{findings.length !== 1 ? 's' : ''} and identified root causes with
        suggested fixes.
      </p>
      <ul className={styles.findingsList}>
        {findings.map(finding => (
          <li key={finding.id}>
            <FindingCard finding={finding} />
          </li>
        ))}
      </ul>
    </div>
  )
}
